import { LightboxOpenOptions } from './common.types';
/**
 * A [popup](https://support.wix.com/en/article/studio-editor-using-popups) opens on a site to grab a site visitor's attention.
 *
 * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
 *
 *  To learn more about popups, see the [Hello Popups](https://dev.wix.com/docs/coding-examples/getting-started/hello-world/hello-popups) example page.
 *
 *  To use the Lightbox API, import `wixWindowFrontend` from the `wix-window-frontend` module:
 *
 *    ```javascript
 *    import wixWindowFrontend from 'wix-window-frontend';
 *    ```
 *
 * The APIs in `wix-window-frontend.Lightbox` can only be used in frontend code.
 */
export interface Lightbox {
    /**
     * Closes a popup.
     *
     * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
     *
     *  The `close()` method closes a popup and allows you to pass data from the popup to the page that opened the popup.
     *  If a popup is closed through the 'X' icon, close button, or popup overlay, data will not be returned to the original page.
     *
     *  To ensure data can be passed:
     *  1. Call this method to close a popup programmatically. For example, add a button with an `onClick` event that calls `close()`.
     *  2. Disable these closing options in the popup's settings under [**Set Triggers**](https://support.wix.com/en/article/studio-editor-using-lightboxes#setting-triggers-for-a-lightbox).
     * @param data - The data to pass back to the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox) method.
     */
    close(data?: object): Promise<void>;
    /**
     * Gets the data object that was passed to a popup.
     *
     * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
     *
     *  Retrieves the data object, if any, that was passed when a popup
     *  was opened with the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox) method.
     *  If a popup was opened in any other way, `getContext()` returns `undefined`.
     *
     *  To pass data to a popup, it must be opened programmatically using the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox)
     *  method. Popups that are opened automatically on page load, or with a link from a page element don't receive passed data.
     *
     * @returns The data object that was passed to the popup.
     */
    getContext(): Promise<object>;
    /**
     * Opens a popup and optionally passes it the specified data.
     *
     * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
     *
     *  The `open()` method opens an app popup by its extension ID and optionally passes data to it. Use this in your app's [site widget](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-widgets/about-site-widget-extensions) to trigger the app's popup. Learn more about [site popup extensions](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-lightboxes/about-site-lightbox-extensions).
     *
     *  To access the data passed to a popup, call [`getContext()`](https://dev.wix.com/docs/sdk/frontend-modules/window/lightbox/get-context) in the popup's code.
     *
     *  If the popup is closed programmatically using [`close()`](https://dev.wix.com/docs/sdk/frontend-modules/window/lightbox/close)
     *  and includes data, the promise returned by `open()` resolves with that data.
     *
     *  Learn more about [opening and closing a popup from your app's code](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-lightboxes/about-site-lightbox-extensions#open-and-close-a-lightbox-from-your-apps-code)
     * @param options - Open popup options.
     * @servicePath wix-window-frontend.LightboxOpenOptions
     * @returns Fulfilled - Resolves with data returned from the popup when it's closed.
     * Rejected - The error that caused the rejection.
     */
    open(options?: LightboxOpenOptions): Promise<object>;
    /**
     * Sets whether the site in the background behind a popup can be scrolled while a popup overlay is open.
     *
     * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
     *
     *  If `backgroundScrollEnabled` is `true`, site visitors can scroll the site in the background behind a popup while a popup overlay is open.
     *
     *  If `backgroundScrollEnabled` is `false`, site visitors can't scroll the site in the background behind a popup while a popup overlay is open.
     *
     *  The default for `backgroundScrollEnabled` is `false`.
     *
     *  > **Note:** This method only affects the site in the background behind a popup. It doesn't affect the scrollability of the popup content itself.
     * @param backgroundScrollEnabled - Whether site visitors can scroll the site in the background behind a popup while a popup overlay is open.
     *
     * Default: `false`
     */
    setBackgroundScroll(backgroundScrollEnabled?: boolean): Promise<void>;
}
/**
 * Closes a popup.
 *
 * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
 *
 *  The `close()` method closes a popup and allows you to pass data from the popup to the page that opened the popup.
 *  If a popup is closed through the 'X' icon, close button, or popup overlay, data will not be returned to the original page.
 *
 *  To ensure data can be passed:
 *  1. Call this method to close a popup programmatically. For example, add a button with an `onClick` event that calls `close()`.
 *  2. Disable these closing options in the popup's settings under [**Set Triggers**](https://support.wix.com/en/article/studio-editor-using-lightboxes#setting-triggers-for-a-lightbox).
 * @param data - The data to pass back to the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox) method.
 */
export function close(data?: object): Promise<void>;
/**
 * Gets the data object that was passed to a popup.
 *
 * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
 *
 *  Retrieves the data object, if any, that was passed when a popup
 *  was opened with the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox) method.
 *  If a popup was opened in any other way, `getContext()` returns `undefined`.
 *
 *  To pass data to a popup, it must be opened programmatically using the [`openLightbox()`](https://dev.wix.com/docs/velo/api-reference/wix-window-frontend/open-lightbox)
 *  method. Popups that are opened automatically on page load, or with a link from a page element don't receive passed data.
 *
 * @returns The data object that was passed to the popup.
 */
export function getContext(): Promise<object>;
/**
 * Opens a popup and optionally passes it the specified data.
 *
 * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
 *
 *  The `open()` method opens an app popup by its extension ID and optionally passes data to it. Use this in your app's [site widget](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-widgets/about-site-widget-extensions) to trigger the app's popup. Learn more about [site popup extensions](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-lightboxes/about-site-lightbox-extensions).
 *
 *  To access the data passed to a popup, call [`getContext()`](https://dev.wix.com/docs/sdk/frontend-modules/window/lightbox/get-context) in the popup's code.
 *
 *  If the popup is closed programmatically using [`close()`](https://dev.wix.com/docs/sdk/frontend-modules/window/lightbox/close)
 *  and includes data, the promise returned by `open()` resolves with that data.
 *
 *  Learn more about [opening and closing a popup from your app's code](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/site-extensions/site-lightboxes/about-site-lightbox-extensions#open-and-close-a-lightbox-from-your-apps-code)
 * @param options - Open popup options.
 * @servicePath wix-window-frontend.LightboxOpenOptions
 * @returns Fulfilled - Resolves with data returned from the popup when it's closed.
 * Rejected - The error that caused the rejection.
 */
export function open(options?: LightboxOpenOptions): Promise<object>;
/**
 * Sets whether the site in the background behind a popup can be scrolled while a popup overlay is open.
 *
 * > **Note:** The terms popup and lightbox refer to the same element. While the editor and dashboard now refer to it as a [popup](https://support.wix.com/en/article/studio-editor-using-popups), the API methods continue to use the term lightbox for backward compatibility. The documentation uses both terms accordingly.
 *
 *  If `backgroundScrollEnabled` is `true`, site visitors can scroll the site in the background behind a popup while a popup overlay is open.
 *
 *  If `backgroundScrollEnabled` is `false`, site visitors can't scroll the site in the background behind a popup while a popup overlay is open.
 *
 *  The default for `backgroundScrollEnabled` is `false`.
 *
 *  > **Note:** This method only affects the site in the background behind a popup. It doesn't affect the scrollability of the popup content itself.
 * @param backgroundScrollEnabled - Whether site visitors can scroll the site in the background behind a popup while a popup overlay is open.
 *
 * Default: `false`
 */
export function setBackgroundScroll(backgroundScrollEnabled?: boolean): Promise<void>;
